var frontierSnapshot = {"generatedAt":"2026-09-21T14:08:55.092Z","cadence":"Every Monday at 07:17 UTC","windowDays":45,"method":"Automated topic matching followed by newest-first ordering. This is a discovery feed, not an impact or efficacy ranking.","sources":[{"id":"europe-pmc","name":"Europe PMC","kind":"paper","url":"https://europepmc.org/RestfulWebService","note":"Newest peer-reviewed and indexed literature matching the atlas topic vocabulary."},{"id":"preprints","name":"Europe PMC preprint index","kind":"preprint","url":"https://europepmc.org/RestfulWebService","note":"Recent preprints indexed from source servers; each item links to its original record and is marked as not yet peer reviewed."},{"id":"clinicaltrials","name":"ClinicalTrials.gov","kind":"trial","url":"https://clinicaltrials.gov/data-api/api","note":"Recently updated registrations, not evidence that a treatment is effective."},{"id":"nibib","name":"NIH NIBIB News","kind":"news","url":"https://www.nibib.nih.gov/rss","note":"Current official biomedical-engineering news feed; item dates are shown as the weekly observation date when the feed omits them."}],"errors":[],"items":[{"id":"trial-nct07592611","kind":"trial","title":"Deep Brain Stimulation for Treatment-Resistant Schizophrenia","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07592611","summary":"The purpose of this pilot study is to investigate the use of deep brain stimulation (DBS) of the substantia nigra pars reticulata (SNr) in subjects with treatment-resistant schizophrenia. There is a subset of patients with schizophrenia who continue to have persistent psychotic symptoms (auditory hallucinations and delusions) despite multiple adequate medication trials with antipsychotic medications including clozapine. There are currently no available treatments for such patients who generally have poor function and are chronically disabled, unable to work, live independently or have meaningful social relations…","authors":"Johns Hopkins University","venue":"NCT07592611 · NA","status":"not yet recruiting","topics":["record","stimulate"]},{"id":"trial-nct07374276","kind":"trial","title":"BCI With Virtual Reality for Stroke Rehabilitation: A Crossover Study","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07374276","summary":"The goal of this clinical trial is to investigate if training sessions of motor imagery associated with brain-computer interface and motor observation through virtual reality (MI-VR-BCI) can help to improve arm and hand recovery after a stroke. The main questions to answer are: * Can adding MI-BCI-VR sessions improve upper limb movement? * Can it help stroke survivors perform daily activities more easily? * Does this type of training improve brain activity and connections related to movement? Researchers will compare this type of intervention with motor imagery associated with a standard brain-computer interface…","authors":"Technical University of Lisbon","venue":"NCT07374276 · NA","status":"active not recruiting","topics":["restore"]},{"id":"trial-nct05933681","kind":"trial","title":"Neurophysiology Biomarkers of Cognitive Impairment Associated With Deep Brain Stimulation","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT05933681","summary":"The study aims to investigate cognitive impairment associated with Deep Brain Stimulation (DBS) in Parkinson's Disease patients, with a focus on identifying neurophysiology biomarkers of DBS associated cognitive changes. Using neurophysiology data recorded during DBS surgeries and post-implantation, the research intends to identify biomarkers in order to optimize electrode placement, enhance programming, and ultimately minimize DBS-related cognitive side effects.","authors":"Vanderbilt University Medical Center","venue":"NCT05933681 · NA","status":"active not recruiting","topics":["record","stimulate"]},{"id":"trial-nct07210112","kind":"trial","title":"Efficacy of Psilocybin and Trazodone Combination in Treatment-resistant Depression: a Randomized Controlled Proof-of-concept Study (PSILOTRAZ)","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07210112","summary":"Psilocybin, a serotonin receptor agonist in the brain, significantly and quickly improves depressive symptoms while inducing profound acute subjective effects. The benefit-risk ratio of psilocybin in treatment-resistant depression seems favorable, but needs to be confirmed. Moreover, the role of 5-HT2A receptors, involved in the psychedelic experience, on the therapeutic efficacy of psilocybin is still poorly understood. For example, pre-administration of trazodone, a 5-HT2A antagonist antidepressant, could annihilate the acute subjective effects of psilocybin without altering its beneficial effects (Rosenblat e…","authors":"Centre Hospitalier St Anne","venue":"NCT07210112 · PHASE2","status":"recruiting","topics":["record"]},{"id":"trial-nct07827456","kind":"trial","title":"MRI-Guided Temporal Interference Stimulation for Parkinson's Disease","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07827456","summary":"This study aims to evaluate the efficacy and safety of tTIS treatment in patients with Parkinson's disease (PD). The study will enroll eligible PD patients and randomly assign them to two groups: Group A will first receive combined GPi and STN stimulation, followed by GPi stimulation one week later; Group B will first receive GPi stimulation, followed by combined GPi and STN stimulation one week later. The MDS-UPDRS Part III will be assessed at pre-stimulation baseline, immediately after stimulation, and at 30 and 60 minutes post-stimulation for each session, in order to evaluate and compare the therapeutic effe…","authors":"Tongji Hospital","venue":"NCT07827456 · NA","status":"not yet recruiting","topics":["stimulate"]},{"id":"trial-nct06577454","kind":"trial","title":"Measuring the Effects of Neurostimulation on Risky and Ambiguous Decision-Making Capacity in People With and Without Substance Use Disorder","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT06577454","summary":"Background: The purpose of this study is to understand how a type of brain stimulation, transcranial magnetic stimulation (TMS), may help those who use opioids such as heroin or methadone. TMS uses brief magnetic pulses to affect brain activity, and is approved by the FDA to treat some mental health problems and substance use. We will evaluate how TMS may help make it easier to make certain kinds of decisions that could help one manage their opioid use. Our findings may provide support for the use of brain stimulation as a treatment to reduce opioid use. Objective: To understand how TMS affects brain activity as…","authors":"National Institute on Drug Abuse (NIDA)","venue":"NCT06577454 · NA","status":"suspended","topics":["record","stimulate"]},{"id":"trial-nct05416294","kind":"trial","title":"Neurostimulation an Adjuvant Postoperative Analgesic in Total Knee Replacement (TKR) Surgeries","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT05416294","summary":"To study and evaluate the effect of using the Primary Relief PENS treatment as adjuvant analgesia for reducing pain in total knee replacement (TKR) patients.","authors":"DyAnsys, Inc.","venue":"NCT05416294 · NA","status":"withdrawn","topics":["record"]},{"id":"trial-nct04658693","kind":"trial","title":"Functional and Neuroprotective Effects of Restoring Lower Limb Sensation After Diabetic Peripheral Neuropathy","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT04658693","summary":"The purpose of this study is to evaluate the effectiveness of providing sensation of the missing limb to individuals with above and below the knee limb loss. The investigators will implanted stimulating electrodes to send small electrical currents to the remaining nerves. These small electrical currents cause the nerves to generate signals that are then transferred to your brain similar to how the information about your foot and lower limb used to be transferred to the brain prior to your limb loss. Additionally, there is the option to have muscle recording electrodes implanted within the muscles of the lower li…","authors":"VA Office of Research and Development","venue":"NCT04658693 · NA","status":"active not recruiting","topics":["record"]},{"id":"trial-nct07805057","kind":"trial","title":"Magnetic Brain Stimulation in Small Fiber Neuropathy","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07805057","summary":"Small fiber neuropathy (SFN) is a condition in which the smallest nerve fibers are damaged. This leads to severe pain and disturbances in the body's automatic functions. As a result, quality of life is often substantially reduced. Pain is one of the main symptoms of small fiber neuropathy. Unfortunately, the effects of currently available pain medications are often disappointing and may be accompanied by unacceptable side effects. Although the smallest nerve fibers do not function properly in SFN, the brain also appears to play a role in the symptoms. Specialized brain imaging studies have shown that brain activ…","authors":"Maastricht University Medical Center","venue":"NCT07805057 · NA","status":"recruiting","topics":["record","stimulate"]},{"id":"trial-nct07832188","kind":"trial","title":"A Study on the Efficacy of Dual-Carrier-Frequency Transcranial Alternating Current Stimulation Modulating the Hippocampus for the Treatment of Chronic Non-Specific Low Back Pain","date":"2026-09-21","observedAt":"2026-09-21","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07832188","summary":"This is a single-center, randomized, double-blind, sham-controlled trial evaluating dual-carrier-frequency transcranial alternating current stimulation targeting the hippocampus in 60 patients with chronic non-specific low back pain. Participants will be randomized into four groups: active stimulation, active stimulation with iTBS, superficial stimulation control, and sham control. All groups will receive standard rehabilitation. The intervention is 20 minutes per session, 5 sessions weekly for 2 weeks (10 sessions total). The primary objective is to assess improvements in pain intensity (VAS) and emotional symp…","authors":"Qilu Hospital of Shandong University","venue":"NCT07832188 · NA","status":"recruiting","topics":["record","stimulate","restore"]},{"id":"paper-10.1016/j.arr.2026.103379","kind":"paper","title":"Unlocking the Blood-Brain Barrier: Can Low-Intensity Focused Ultrasound Enable Effective Delivery of Anti-Amyloid and Anti-Tau Antibodies in Alzheimer's Disease?","date":"2026-09-20","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.arr.2026.103379","summary":"Alzheimer's disease (AD) remains a major unmet medical challenge despite decades of progress in medicines that target tau and amyloid-β (Aβ) pathology. The clinical benefit of monoclonal antibodies (mAbs) against Aβ is limited, with current data showing only slight slowing of cognitive decline despite encouraging biomarker responses and recent regulatory approval of these drugs. Moreover, their wider clinical use is restricted by dose-dependent toxicities such as amyloid-related imaging abnormalities (ARIA), and by the need for continuous long-term assessment of efficacy and safety in AD patients. The poor penet…","authors":"Desale SH, Doshi PP, Khutale AA, Suresh S.","venue":"Ageing research reviews","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.1016/j.expneurol.2026.116033","kind":"paper","title":"Sex differences in the effects of deep brain stimulation on traumatic brain injury-induced cognitive deficits in rats.","date":"2026-09-20","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.expneurol.2026.116033","summary":"Traumatic brain injury (TBI) is often associated with cognitive impairments, with episodic memory deficits among the most prevalent sequelae. While clinical evidence indicates that females tend to experience worse long-term cognitive outcomes following TBI, biological sex remains poorly characterized in preclinical neuromodulation studies. Deep brain stimulation (DBS) has emerged as a promising neuromodulatory approach for cognitive rehabilitation, but its sex-dependent efficacy following TBI remains poorly understood. We investigated the effects of chronic anterior nucleus of the thalamus (ANT) DBS on spatial l…","authors":"Robson IK, Rabelo TK, Almeida Souza TH, McCann E, Bittencourt GN, Surendrakumar S, Nestor SM, Goubran M, Covolan L, Montenegro MLS, Lipsman N, Hamani C.","venue":"Experimental neurology","status":"Peer-reviewed / indexed","topics":["record","stimulate","restore"]},{"id":"paper-10.1007/s10484-026-09808-3","kind":"paper","title":"Neurofeedback-Guided Motor Imagery in Chronic Stroke: A Case Series on Upper-Limb Recovery, Cortical Activation, and Brain Symmetry.","date":"2026-09-20","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1007/s10484-026-09808-3","summary":"Brain-computer interface (BCI) systems combined with motor imagery (MI) have emerged as promising tools in neurorehabilitation. Real-time neurofeedback may further enhance motor recovery by promoting use-dependent neuroplasticity; however, evidence in chronic stroke remains limited, particularly from controlled pilot studies. This case series explored the feasibility and preliminary effects of EEG-based BCI neurofeedback combined with MI and physiotherapy on upper-limb motor function and brain activation patterns in individuals with chronic stroke. In a double-blind, controlled protocol, seven individuals with c…","authors":"Carvalho R, Azevedo E, Marques P, Dias N, Cerqueira JJ.","venue":"Applied psychophysiology and biofeedback","status":"Peer-reviewed / indexed","topics":["record","restore","personal"]},{"id":"paper-10.1007/s00415-026-14137-w","kind":"paper","title":"Visual snow syndrome as a neuropsychiatric network disorder: clinical features, mechanisms, and therapeutic perspectives.","date":"2026-09-20","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1007/s00415-026-14137-w","summary":"Visual Snow Syndrome (VSS) is a neurological condition characterized by the persistent perception of dynamic, flickering, dot-like visual disturbances across the entire visual field, resembling television static. Increasing evidence indicates that VSS is frequently accompanied by a broad spectrum of psychiatric symptoms, including anxiety, depression, depersonalization, fatigue, and sleep disturbances, all of which substantially impair quality of life. Although the pathogenesis of VSS remains incompletely understood, Current evidence increasingly suggests that VSS may represent a multisystem neuropsychiatric net…","authors":"Huang Q, Wang J, Zhao L, Yu X, Wang W, Wang Z, Liu Y.","venue":"Journal of neurology","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.09.18.26363360","kind":"preprint","title":"Low-Intensity Focused Ultrasound of the Amygdala in Depression and Anxiety: A First-in-Human Active-Controlled Trial","date":"2026-09-20","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.18.26363360","summary":"ABSTRACT Background: Low intensity focused ultrasound (FUS) offers a noninvasive method for directly modulating deep brain structures with millimeter-scale precision, potentially addressing a major limitation of existing noninvasive neuromodulation approaches. The amygdala is a key node in affective neurocircuitry and a compelling target for psychiatric intervention. We conducted a first in human active controlled trial ( NCT05147142 ) of amygdala-targeted FUS in patients with major depressive disorder, examining safety and target engagement. Methods: Ten participants with major depressive disorder completed a s…","authors":"Arulpragasam AR, van 't Wout-Frank M, Berlow YA, Aiken E, Gorbatov A, Van Patten R, Gillotti JG, Swearingen HR, Faucher CR, Adams H, McLaughlin NC, Liberzon I, Barredo J, Correia S, Greenberg B, Philip NS.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.21203/rs.3.rs-10142978/v1","kind":"preprint","title":"An Intraoperative Study of Speech-Related Neuronal Activity in the Subthalamic Nucleus of Parkinson's Disease Patients","date":"2026-09-20","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-10142978/v1","summary":"Abstract Background The subthalamic nucleus (STN) is an important deep brain stimulation (DBS) target in the treatment of Parkinson's disease (PD). While DBS significantly improves motor functioning, its effect on speech varies. Methods We analyze intraoperative STN single-neuron activity from 13 PD patients performing a diadochokinetic task involving sequential repetition of /pa/-/ta/-/ka/ syllables and a hand motor task. Results Here we isolate 128 STN neurons and identify 61 neurons related to various aspects of the speech task, and 41 neurons related to the production of /pa/, /ta/, and /ka/ syllables. Speec…","authors":"Sieger T, Novotný M, Serranová T, Růžička F, Krýže P, Mana J, Lasica A, May J, Urgošík D, Rusz J, Jech R.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"paper-10.1038/s41380-026-03913-9","kind":"paper","title":"An mPFC-DMV cortical-autonomic-immune axis governs stress-induced immune dysregulation in sepsis.","date":"2026-09-19","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1038/s41380-026-03913-9","summary":"Chronic psychological stress is a major predisposing factor that worsens sepsis outcomes, yet the neural mechanisms linking stress exposure to immune dysregulation remain poorly understood. Here, using a mouse model of chronic restraint stress (CRS) followed by endotoxemia, we show that prior stress markedly aggravates mortality, systemic inflammation, and immune imbalance during sepsis. Mechanistically, we identify a stress-sensitive medial prefrontal cortex (mPFC)-dorsal motor nucleus of the vagus (DMV) circuit that functions as a central regulator of peripheral neuroimmune homeostasis. Chronic stress is assoc…","authors":"Yin L, Liu F, Li M, Wang Y, Liu L, Zhang X, Fan Z, Gu T, Guo Y, Wang D, Zhao G, Guo Y, Ma H, Han J, Zhang X.","venue":"Molecular psychiatry","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.12659/ajcr.954251","kind":"paper","title":"Pulsed Radiofrequency of the Sacral Dorsal Root Ganglia as a Potential Rescue Therapy for Refractory Chronic Pelvic Pain: A Case Series.","date":"2026-09-19","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.12659/ajcr.954251","summary":"BACKGROUND Chronic pelvic pain (CPP) is a prevalent, multifactorial condition with neuropathic, visceral, myofascial, and psychogenic components; a subset of patients remain refractory to multimodal pharmacotherapy and conventional interventional procedures. Pulsed radiofrequency (PRF) of the dorsal root ganglia (DRG) is a minimally invasive neuromodulatory technique that can attenuate pathological nociceptive transmission while preserving neural integrity. We describe 3 patients with severe, treatment-refractory CPP of predominantly neuropathic origin who underwent sacral DRG PRF as rescue therapy. CASE REPORT…","authors":"Gogol P, Gierczak M, Szczepaniak R, Wiśniewski R, Sobstyl M, Pasztaleniec R, Grabarek BO.","venue":"The American journal of case reports","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"preprint-10.31234/osf.io/8x7gv_v2","kind":"preprint","title":"Emotion recognition in neurotechnology: A scientific and technical fact check","date":"2026-09-19","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.31234/osf.io/8x7gv_v2","summary":"Consumer neurotechnology systems that are claimed to be able to infer human emotions from facial expressions, voice, and physiological signals are increasingly deployed in domains such as marketing, education, human resources, and mental health. As these systems have moved beyond clinical and research settings into consumer markets, their purported capacity to infer users’ internal states has become increasingly relevant to everyday life. More recently, emerging neurotechnologies have extended these claims by suggesting that emotional states can be detected directly from neural data using artificial intelligence…","authors":"Schreiter ML.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","compute","personal"]},{"id":"paper-10.3791/73867","kind":"paper","title":"Central Mechanisms of Electroacupuncture in Chronic Heart Failure: Insights from Quantitative Proteomics of the Nucleus Tractus Solitarius.","date":"2026-09-18","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.3791/73867","summary":"Chronic heart failure (CHF) is a leading global cause of cardiovascular mortality, driven by autonomic dysregulation and sympathetic overactivation. While electroacupuncture (EA) exerts cardioprotective effects via central neuromodulation, its specific molecular targets within the nucleus tractus solitarius (NTS), a key autonomic integration center, remain unclear. To investigate this, the CHF rat model was established via left anterior descending coronary artery ligation. Rats received EA at bilateral HT7 acupoints for seven consecutive days. Cardiac function and myocardial injury were evaluated using echocardi…","authors":"Guo Y, Xu W, Zhang Z, Zhao X, Wang J, Wu H, Xu N, Zhou M, Wu S.","venue":"Journal of visualized experiments : JoVE","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.3171/2026.3.jns252633","kind":"paper","title":"Re-evaluating sources of electrode deviation in deep brain stimulation: surgical technique versus patient-specific brain mechanics.","date":"2026-09-18","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.3171/2026.3.jns252633","summary":"Objective Accurate electrode placement is crucial for optimizing outcomes in deep brain stimulation (DBS). Although reported mean radial deviations are 1.5 mm, a substantial amount deviate more than 2 mm, necessitating revision. Studies to date have largely focused on improving surgical techniques to improve target accuracy, but the role of brain mechanics remains understudied. The aim of this study was to evaluate MR elastography (MRE)-derived patient-specific mechanical factors, as well as surgical technique factors, as contributors to electrode deviation in DBS. Methods Seventeen patients undergoing DBS to tr…","authors":"Zhou B, Ziechmann R, Chen S, Mann K, Kramer MK, Kroen MB, Alizadeh M, Mohamed FB, Johnson CL, Wu Q, Wu C.","venue":"Journal of neurosurgery","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.3171/2026.4.jns252510","kind":"paper","title":"Association between choroid plexus susceptibility features and motor outcomes following deep brain stimulation in Parkinson's disease.","date":"2026-09-18","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.3171/2026.4.jns252510","summary":"Objective Deep brain stimulation (DBS) of the subthalamic nucleus (STN) is an effective therapy for advanced Parkinson's disease (PD), but postoperative motor outcomes show substantial interindividual variability. Recent evidence suggests choroid plexus (ChP) dysfunction in PD pathophysiology. This study aimed to investigate the association between preoperative ChP MRI characteristics and postoperative motor outcomes following STN-DBS in PD patients. Methods Forty-one PD patients who underwent bilateral STN-DBS were included for final analysis. Motor outcomes were assessed using the Movement Disorder Society-Uni…","authors":"Fang S, Yang C, Tang Y, Chen L, Zhao W, Ma C, Li G, Wu X, Li J.","venue":"Journal of neurosurgery","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.1016/j.brs.2026.103207","kind":"paper","title":"Subthalamic DBS Engages Right-lateralized Frontal Control to Improve Gait Adaptation in Parkinson's Disease.","date":"2026-09-18","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.brs.2026.103207","summary":"Background Successful walking requires continuous adaptation to changing environmental demands, a process that is frequently impaired in Parkinson's disease (PD). The neural mechanisms by which subthalamic nucleus deep brain stimulation (STN-DBS) modulates adaptive gait control remain unclear. Objective To characterize the clinical, kinematic, metabolic, and cortical electrophysiological correlates of gait adaptation in PD and their modulation by STN-DBS during dynamic obstacle avoidance. Methods We evaluated gait-adaptation kinematics and electroencephalography (EEG) in twelve PD patients during an immersive vi…","authors":"Hanafi I, Pozzi NG, Habib R, Falciglia S, Del Vecchio Del Vecchio J, Remore LG, Marotta G, Buck A, Pezzoli G, Volkmann J, Isaias IU, Palmisano C.","venue":"Brain stimulation","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.1016/j.exer.2026.111241","kind":"paper","title":"Multimodal Approaches to Visual Experimental Research: Imaging, Electrophysiology, and Behavior.","date":"2026-09-18","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.exer.2026.111241","summary":"Although vision is one of the primary senses in humans, direct mechanistic research in patients is challenging both technically and ethically because of its multiscale complexity-spanning phototransduction, neural processing, and perception. The foundation of visual science is animal models, which offer controlled, systematic assess to every stage of the visual pathway. Animal models' visual phenotyping methods are highly significant for vision-related research. However, the selection of various experimental methods and critical differences between them are frequently disregarded in study design. To address this…","authors":"Zhong J, Zhang H, Li J, Zhou H.","venue":"Experimental eye research","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"paper-10.1016/j.neuroimage.2026.122243","kind":"paper","title":"Neuroanatomical Predictors of Frontal tDCS Current Distribution in Cognitively Healthy Older Adults.","date":"2026-09-18","observedAt":"2026-09-21","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.neuroimage.2026.122243","summary":"Transcranial direct current stimulation (tDCS) is a noninvasive neuromodulation technique with the potential to mitigate age-related cognitive decline, yet most models do not account for the substantial anatomical variability of older adults. We aimed to identify neuroanatomical predictors of brain current density (Jbrain) during bilateral frontal tDCS using individualized, high-fidelity head models. We constructed 11-tissue MRI-based models in 367 cognitively healthy older adults (Mean age = 71.64 years), representing, to our knowledge, the largest manually corrected 11-tissue dataset of this kind to date. The…","authors":"Busch TA, Stolte SE, Dai Y, O'Shea A, Iversen K, Pedersen S, Hart G, Chen J, Shukla P, Albizu A, Fang R, Woods AJ, Indahlastari A.","venue":"NeuroImage","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.09.16.746058","kind":"preprint","title":"Adolescent development accelerates responses to input in human neocortical neurons","date":"2026-09-18","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.16.746058","summary":"Through childhood and adolescence, profound changes to the physiology of individual neurons accompany large-scale network changes in the mammalian neocortex. These physiological changes are well understood in rodent models but far less is known in the human neocortex. Here we combine patch-clamp electrophysiology and single-cell sequencing (Patch-Seq) in neurosurgically-resected pediatric human brain slices and age-matched mouse brain slices to elucidate the unique developmental trajectory of human neurons. We find that human Layer 2/3 pyramidal neurons show distinctive postnatal changes in neuronal physiology t…","authors":"Owen SF, Kendrick RM, Clark JK, Leonard EP, Ramasamy N, DeLope SS, Phillips HW, Buch VP, Mahaney KB, Grant GA, Prolo LM.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.64898/2026.09.13.26362955","kind":"preprint","title":"AI agents at the brain-computer interface: separating inference from control","date":"2026-09-17","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.13.26362955","summary":"In medicine, AI agents are moving from generating text to executing actions, making uncertainty from upstream decoders a control problem. We studied this at the brain-computer interface using 1,065 episodes from 47 people with amyotrophic lateral sclerosis and five language models. Prompting agents with reconstructed decoder confidence never reduced unfaithful execution below a deterministic gate at matched coverage; two models were significantly worse. Apparent safety gains of up to 22 percentage points reflected acting less often, sometimes through invalid tool calls rather than explicit abstention. A post-hoc…","authors":"Gorenshtein A, Omar M, Jia EL, Adiniaev Y, Daniel O, Kruskal J, Ahmed M, Brook OR, Klang E, Barash Y.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["restore"]},{"id":"preprint-10.20944/preprints202609.1459.v1","kind":"preprint","title":"Hybrid EEG–EOG Brain–Computer Interface for Virtual-Reality Powered Mobility Training in Children with Severe Neuromotor Disabilities: A Multiple-Case Feasibility Study","date":"2026-09-17","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.20944/preprints202609.1459.v1","summary":"Background: Developing Brain–Computer Interfaces (BCIs) for children with severe neuromotor disabilities remains challenging due to developmental neurophysiology and the high cognitive demands of motor imagery. Hybrid BCIs integrating electroencephalography (EEG) and electrooculography (EOG) can overcome these limitations by combining continuous motor-related control with reliable discrete commands. This multiple-case study investigated the feasibility of a hybrid EEG–EOG BCI integrated with a virtual reality (VR) powered-wheelchair simulator for mobility training. Methods: Six participants (one child, five adol…","authors":"Marcaccini K, Pulvirenti F, Pierotti F, Dellarole L, Bianco M, Piermaria G, Tampellini F, Moscato S, Tonin L, Tortora S, Chiari L, Cersosimo A, Orlandi S.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.31234/osf.io/d7uqw_v1","kind":"preprint","title":"Transcranial ultrasound stimulation as a tool to causally modulate the human hippocampus","date":"2026-09-17","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.31234/osf.io/d7uqw_v1","summary":"Background: Non-invasive brain stimulation has, until recently, had limited effect on deep brain circuits critical for memory. Transcranial ultrasound stimulation (TUS) has emerged as a promising tool to address this limitation. By delivering spatially focused acoustic energy, TUS enables targeted modulation of deep brain structures such as the hippocampus. TUS therefore provides new opportunities to causally modulate activity in neural circuits important for memory. Objective: This perspective discusses how TUS provides a potential methodological advance for human memory research, examining the mechanistic basi…","authors":"McFarland C, Klein-Flugge M, Barron H, Mancini V.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.21203/rs.3.rs-10919819/v1","kind":"preprint","title":"Gait-phase-dependent neural dynamics differ between treated Parkinson’s disease and healthy controls","date":"2026-09-17","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-10919819/v1","summary":"Abstract Gait disturbances in Parkinson's disease (PD) often persist despite dopaminergic medication and subthalamic nucleus deep brain stimulation (STN-DBS), yet the neural activity accompanying gait under combined therapy remains incompletely understood. We recorded mobile electroencephalography (EEG), STN local field potentials (PD only), and motion capture during overground walking in 10 individuals with PD under combined STN-DBS and dopaminergic therapy and 10 age-matched healthy controls (HC). Overall spectral characteristics showed few PD--HC differences and no significant rest-versus-walking differences…","authors":"Salzmann L, Brunner AS, Mei Z, Fleisch A, Taylor WR, Peterson V, Imbach L, Ravi DK, Lambercy O, Gassert R.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.21203/rs.3.rs-10591570/v1","kind":"preprint","title":"Convergence of Artificial Intelligence and Cognitive Neuroscience Innovations and Future Directions","date":"2026-09-17","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-10591570/v1","summary":"Abstract The convergence of Artificial Intelligence (AI) and Cognitive Neuroscience has emerged as one of the most significant interdisciplinary developments in contemporary science and technology. While AI seeks to develop computational systems capable of performing tasks traditionally associated with human intelligence, Cognitive Neuroscience investigates the neural mechanisms underlying cognition, perception, learning, memory, language, and decision-making. This article examines the theoretical foundations, historical evolution, and practical applications of the relationship between AI and Cognitive Neuroscie…","authors":"Ukpong UJ, Chetachi OM.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["compute"]},{"id":"preprint-10.64898/2026.09.14.751475","kind":"preprint","title":"Precision cooling assists electrical stimulation: Breaking selectivity barriers in nerve control","date":"2026-09-16","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.14.751475","summary":"Peripheral neuromodulation can relieve pain through sensory activation or conduction block. However, electrical stimulation of mixed nerves couples these intended effects to unwanted neural activity. Here we demonstrate local cooling can separate targeted from off-target neural activity. In the rat sciatic nerve, precooling reduced the onset response to kilohertz–frequency stimulation by about 90% and maintained block in the target pathway during rewarming. During low–frequency stimulation, spatially graded cooling suppressed Aδ enriched activity and blocked nontarget propagation. This produced a directional, Aβ…","authors":"Yang S, Yu X, Yang S, Wang Q, Bi G, Liu Y, Du Z.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate","compute"]},{"id":"preprint-10.64898/2026.09.11.750608","kind":"preprint","title":"Spatiotemporal characterization of corticolimbic dopamine and noradrenaline signaling and affective state modulation by mfb stimulation","date":"2026-09-16","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.11.750608","summary":"Background: Deep brain stimulation of the medial forebrain bundle (mfb DBS) is a promising intervention for psychiatric disorders, but the neurochemical mechanisms underlying its effects remain incompletely understood. Methods: In adult Sprague Dawley rats, fiber photometry was used to monitor mfb-DBS evoked dopamine (DA) and noradrenaline (NA)-signaling in the nucleus accumbens (NAc) and prefrontal cortex (PFC), following different stimulation patterns, laterality conditions, and prolonged stimulation paradigms. Ultrasonic vocalizations (USVs) were recorded in parallel as a behavioral measure. Results: Bilatera…","authors":"Duan Z, Tong Y, Georgescu A, Coenen VA, Dobrossy M.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.64898/2026.09.11.750896","kind":"preprint","title":"MRSIPrep: A Standardized Post-Quantification Framework for Preprocessing Whole-Brain Magnetic Resonance Spectroscopic Imaging","date":"2026-09-16","observedAt":"2026-09-21","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.11.750896","summary":"Magnetic resonance spectroscopic imaging (MRSI) enables non-invasive mapping of neurometabolites levels across the human brain. Although spectral fitting and metabolite quantification are increasingly supported by mature software tools, the downstream processing of quantified metabolite maps remains heterogeneous across laboratories. Here, we introduce MRSIPrep, an open-source, modular, and reproducible post-quantification framework for whole-brain MRSI. MRSIPrep standardizes quality control, tissue correction, spatial normalization, atlas projection, and derivative generation from quantified metabolite maps and…","authors":"Lucchetti F, Céléreau E, Jenni R, Ledoux J, Eliez S, Delavari F, Hagmann P, Alemán-Gómez Y, Klauser A, Klauser P.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"news-nibib-0-nih-demystifies-vital-biomedical-tech-congressional-staff","kind":"news","title":"NIH Demystifies Vital Biomedical Tech for Congressional Staff","date":"2025-08-15","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/nih-demystifies-vital-biomedical-tech-congressional-staff","summary":"Biomedical engineers and imaging researchers gave 45 congressional staff a glimpse of transformative medical technologies on the horizon, underscoring the crucial role of medical tools in human health. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-1-innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","kind":"news","title":"Innovative imaging tool could improve diagnosis and treatment of hearing loss","date":"2025-08-04","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","summary":"Researchers from the Keck School of Medicine of USC with NIH funding including NIBIB have adapted a low-cost imaging method developed for ophthalmology and used it to visualize tiny structures in the human inner ear. &nbsp; Source: USC Keck School of Medicine News. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-2-scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","kind":"news","title":"Scientists Develop High-Performance MRI Scanner in Effort to Define Microscopic Brain Structures","date":"2025-07-16","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","summary":"A scientific team supported in part by NIH has developed a new, ultra-high-resolution brain imaging system that can reconstruct microscopic brain structures that are disrupted in neurological and neuropsychiatric brain disorders. The new system is a significant advance over conventional magnetic resonance imaging (MRI) scanners that cannot visualize these tiny but clinically important structures. Source: NIH More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-3-high-tech-sticker-can-identify-real-human-emotions","kind":"news","title":"High-tech sticker can identify real human emotions","date":"2025-04-22","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/high-tech-sticker-can-identify-real-human-emotions","summary":"Saying one thing while feeling another is part of being human, but bottling up emotions can have serious psychological consequences like anxiety or panic attacks. To help health care providers tell the difference, a team led by scientists at Penn State has created a stretchable, rechargeable sticker that can detect real emotions — by measuring things like skin temperature and heart rate — even when users put on a brave face. &nbsp;The researchers recently unveiled the wearable patch that can simultaneously and accurately track multiple emotional signals in a study published in the journal Nano Letters. Read more…","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-4-your-skin-breathing-new-wearable-device-can-measure-it","kind":"news","title":"Your skin is breathing. This new wearable device can measure it.","date":"2025-04-10","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/your-skin-breathing-new-wearable-device-can-measure-it","summary":"Northwestern University researchers have developed the first wearable device for measuring gases emitted from and absorbed by the skin. By analyzing these gases, the device offers an entirely new way to assess skin health, including monitoring wounds, detecting skin infections, tracking hydration levels, quantifying exposure to harmful environmental chemicals and more. Source: Northwestern Now More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-5-ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","kind":"news","title":"AI tool can track effectiveness of multiple sclerosis treatments","date":"2025-04-08","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","summary":"A new artificial intelligence (AI) tool that can help interpret and assess how well treatments are working for patients with multiple sclerosis (MS) has been developed by University College London researchers. Source: University College London News More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["compute"]},{"id":"news-nibib-6-revealing-capillaries-cells-living-organs-ultrasound","kind":"news","title":"Revealing capillaries and cells in living organs with ultrasound","date":"2025-04-04","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/revealing-capillaries-cells-living-organs-ultrasound","summary":"While medical centers use ultrasound daily, so far this technology has not been capable of observing body tissues at the scale of cells. Physicists at several universities including CalTech have now developed a microscopy technique based on ultrasound to reveal capillaries and cells across living organs -- something that wasn't possible before. Source: Delft University of Technology More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]},{"id":"news-nibib-7-decreasing-invasiveness-deep-brain-stimulation","kind":"news","title":"Decreasing the invasiveness of deep brain stimulation","date":"2025-03-20","observedAt":"2026-09-21","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/decreasing-invasiveness-deep-brain-stimulation","summary":"Researchers are developing a preclinical method to stimulate the brain without drilling into the skull by guiding a catheter through the cerebrospinal fluid. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]}]};
